import React, { useRef } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Sequence,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SalesMarketingHandshakeProps = Record<string, any>;

const SalesMarketingHandshake: React.FC<SalesMarketingHandshakeProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  primaryColor = "#00FF9A",
  secondaryColor = "#ffffff",
  text1 = "SHOW RATES",
  text2 = "CLOSE RATES",
  text3 = "SPEED TO LEAD",
  durationInSeconds = 8,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Constants & Layout ---
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const RED_COLOR = "#FF4444"; // Hardcoded for requested "Red X" bottleneck indicator

  // Sizing relative to canvas
  const isLandscape = width >= height;
  const baseScale = Math.min(width, height) / 1080;
  
  // Typography
  const fontFamily = "Inter, sans-serif";
  const labelSize = 32 * baseScale;
  const circleRadius = 60 * baseScale;
  
  // Layout
  const items = [text1, text2, text3];
  const totalItems = items.length;
  // Distribute items across 80% of width
  const containerWidth = width * 0.8;
  const itemSpacing = containerWidth / (totalItems + 1); // rough distribution logic usually, but let's do flex evenly
  
  // Animation Timing
  const staggerFrames = 45; // Delay between each node
  const introDelay = 15;

  const renderNode = (text: string, index: number) => {
    const startFrame = introDelay + index * staggerFrames;
    
    // 1. Circle Scale Entrance
    const entrance = spring({
      frame: frame - startFrame,
      fps,
      config: { damping: 14, stiffness: 120 },
    });
    
    // 2. Text Fade & Slide
    const textOpacity = interpolate(frame, [startFrame + 10, startFrame + 30], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    const textSlide = interpolate(
      frame, 
      [startFrame + 10, startFrame + 30], 
      [20 * baseScale, 0], 
      { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: (t) => t* (2-t) }
    );

    // 3. Red X Pop (Bottleneck Indicator)
    const xStartFrame = startFrame + 25;
    const xScale = spring({
      frame: frame - xStartFrame,
      fps,
      config: { damping: 10, stiffness: 200 },
    });

    return (
      <div
        key={index}
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          position: "relative",
          width: circleRadius * 3, // allocate space
        }}
      >
        {/* Circle Node */}
        <div
          style={{
            width: circleRadius * 2,
            height: circleRadius * 2,
            borderRadius: "50%",
            border: `${4 * baseScale}px solid ${secondaryColor}`,
            backgroundColor: bgColor, // Opaque to hide line behind
            transform: `scale(${entrance})`,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            boxShadow: `0 0 ${20 * baseScale}px ${primaryColor}40`, // Subtle neon accent glow
            zIndex: 2,
            position: "relative",
          }}
        >
          {/* Inner Dot Accent */}
          <div 
             style={{
                width: circleRadius * 0.2,
                height: circleRadius * 0.2,
                borderRadius: "50%",
                backgroundColor: primaryColor,
                opacity: entrance,
             }}
          />

          {/* Red X Indicator (Bottleneck) - Positioned Top Right */}
          <div
            style={{
              position: "absolute",
              top: -circleRadius * 0.2,
              right: -circleRadius * 0.2,
              width: circleRadius * 0.8,
              height: circleRadius * 0.8,
              transform: `scale(${xScale})`,
              zIndex: 3,
            }}
          >
             <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <circle cx="12" cy="12" r="11" fill={bgColor} />
                <path d="M16 8L8 16M8 8L16 16" stroke={RED_COLOR} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>
             </svg>
          </div>
        </div>

        {/* Label Text */}
        <h2
          style={{
            marginTop: 20 * baseScale,
            fontFamily,
            fontWeight: 700,
            fontSize: labelSize,
            color: secondaryColor,
            textAlign: "center",
            opacity: textOpacity,
            transform: `translateY(${textSlide}px)`,
            letterSpacing: "-0.04em", // Tight tracking (-40 approx)
            whiteSpace: "nowrap",
            textTransform: "uppercase",
            textShadow: `0 2px 10px rgba(0,0,0,0.8)`,
          }}
        >
          {text}
        </h2>
      </div>
    );
  };

  // Dotted Line Animation
  // Creates a seamless left-to-right flow
  const dotSpacing = 40 * baseScale;
  const lineOffset = (frame * (3 * baseScale)) % dotSpacing;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Container for Centered Layout */}
      <AbsoluteFill 
        style={{ 
          justifyContent: "center", 
          alignItems: "center",
          flexDirection: "row",
          paddingLeft: "10%",
          paddingRight: "10%",
        }}
      >
        
        {/* Flowing Dotted Line (Background Layer) */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: "50%",
            height: 4 * baseScale,
            marginTop: -2 * baseScale - (labelSize / 1.5), // Adjust slightly up to align with circle centers
            overflow: "hidden",
            opacity: 0.6,
            zIndex: 0,
          }}
        >
            <div
                style={{
                    width: "100%",
                    height: "100%",
                    backgroundImage: `linear-gradient(90deg, ${secondaryColor} 0%, ${secondaryColor} 50%, transparent 50%)`,
                    backgroundSize: `${dotSpacing}px 100%`,
                    transform: `translateX(-${lineOffset}px)`, // Negative to flow L -> R if we view the window moving
                    // Actually, to flow Left to Right, the pattern should move Positive.
                    // Let's use backgroundPosition.
                    backgroundPositionX: `${frame * 3}px`,
                    boxShadow: `0 0 ${15 * baseScale}px ${primaryColor}`, // Glowing white/green line
                }}
            />
        </div>

        {/* Nodes Container */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            justifyContent: "space-around",
            alignItems: "flex-start", // Top align so texts hang down evenly
            width: "100%",
            zIndex: 1,
            // Offset vertically to account for text below circle, keeping circles on the line
            transform: `translateY(-${labelSize}px)` 
          }}
        >
          {items.map((txt, idx) => renderNode(txt, idx))}
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default SalesMarketingHandshake;